using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends a custom request; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.CustomRequestResult> SendCustomRequestAsync(string method = default, string parameters = default)
    {

           using var activity =  StartCallActivity("SendCustomRequestAsync", typeof(SendCustomRequest).FullName ?? "SendCustomRequestAsync");

           try
           {
             return client.SendCustomRequestAsync(method, parameters);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
